let lastForwardedContact=0;
function recoverOnContact(event){
 const target=event.target instanceof Element?event.target:null,blocked=getComputedStyle(document.documentElement).pointerEvents==='none'||getComputedStyle(document.body).pointerEvents==='none'||getComputedStyle(app).pointerEvents==='none',backdrop=target?.closest('.detail-modal-backdrop,.sidebar-backdrop');
 if(blocked||backdrop)recoverInteractivity();
 if(!backdrop||target?.closest('[role="dialog"]'))return;
 const contact=event.touches?.[0]||event.changedTouches?.[0]||event,{clientX,clientY}=contact,now=Date.now();
 backdrop.remove();recoverInteractivity();
 const underneath=Number.isFinite(clientX)&&Number.isFinite(clientY)?document.elementFromPoint(clientX,clientY):null,control=underneath?.closest?.('[data-palace-dock] button,[data-v6-nav],[data-palace-rooms]');
 if(!control||now-lastForwardedContact<250)return;
 lastForwardedContact=now;event.preventDefault?.();queueMicrotask(()=>control.isConnected&&control.click());
}
const titleOf=(row,fallback='Untitled')=>text(row?.title||row?.text||row?.name||row?.label||row?.client||row?.clientName)||fallback;
const timeOf=row=>text(row?.startTime||row?.time),dateOf=row=>text(row?.date||row?.dueDate||row?.startDate);
const duration=(start,end,fallback=0)=>{if(!/^\d{1,2}:\d{2}$/.test(text(start))||!/^\d{1,2}:\d{2}$/.test(text(end)))return fallback;const[a,b]=[start,end].map(value=>{const[h,m]=value.split(':').map(Number);return h*60+m});return b<a?b+1440-a:b-a};
const daysFrom=(date,count=7)=>Array.from({length:count},(_,index)=>{const value=new Date(`${date}T12:00:00`);value.setDate(value.getDate()+index);return value.toISOString().slice(0,10)});
const sundayOf=date=>{const value=new Date(`${date}T12:00:00`);value.setDate(value.getDate()-value.getDay());return value.toISOString().slice(0,10)};
const localClock=()=>{const now=new Date;return now.getHours()*60+now.getMinutes()};

function data(view){
 const snapshot=snapshotV4(),date=snapshot.today||localDateKey(),state=snapshot.state||{},daily=['home','time','daily'].includes(view)?selectDailyShit(state,date,{mode:mode()}):{today:[],could:[],routines:[],open:[],done:[]},health=['home','daily'].includes(view)?selectMedicationCabinet(state,date):{items:[],taken:[],open:[]},work=['home','time','boss'].includes(view)?selectWorkHQ(state,date):{todaySessions:[],upcoming:[],occurrences:[],weeklyHours:{}},school=['home','study'].includes(view)?selectStudyNook(state,date):{deadlines:[],progress:{}},finance=['home','boss','money'].includes(view)?selectV5MoneyGig(date):{bills:[],goals:[],pendingPayouts:[],hq:{accounts:[]},accountBalances:{},gigWeek:{}},life=['home','daily','hobbies'].includes(view)?selectLifestyle(state,date):{movement:{},hobbies:{},growth:{}},fixed=[],flexible=[],seen=new Set;
 const addFixed=(kind,row,extra={})=>{const start=timeOf(row),key=`${dateOf(row)}:${start}:${titleOf(row)}`.toLowerCase();if(dateOf(row)!==date||!start||seen.has(key))return;seen.add(key);const enteredPrep=Number(row.prepMinutes||row.preparationMinutes)||0;fixed.push({key,kind,title:extra.title||titleOf(row),startTime:start,endTime:text(row.endTime),duration:Number(row.duration||row.minutes||row.scheduledMinutes)||duration(start,row.endTime,60),prepMinutes:enteredPrep||extra.prepMinutes||0,enteredPrepMinutes:enteredPrep,leaveTime:text(row.leaveTime||row.leaveBy),location:text(row.location||row.station||row.zone),sourceId:text(row.id),meta:extra.meta||''})};
 list(state?.life?.events).forEach(row=>addFixed('event',row,{prepMinutes:15}));list(state?.work?.gigShifts).filter(row=>!row.archivedAt).forEach(row=>addFixed('gig',row,{title:/flex/i.test(text(row.source))?'Amazon Flex block':titleOf(row,'Gig shift'),prepMinutes:25,meta:row.targetAmount?`${money(row.targetAmount)} expected`:''}));list(work.todaySessions).forEach(row=>addFixed('work',{...row,date},{title:titleOf(row,'Client session'),prepMinutes:30}));
 const addFlex=(kind,row,priority=30)=>{if(!row?.id)return;flexible.push({key:`${kind}:${row.id}`,kind,title:titleOf(row),duration:Math.max(5,Number(row.duration||row.minutes)||15),priority,firstMove:text(row.firstStep||row.tinyStart)||'Open it and choose the smallest move.'})};
 list(daily.today).forEach(row=>addFlex(row.kind,row,row.hard?100:75));list(daily.could).forEach(row=>addFlex(row.kind,row,30));list(daily.routines).filter(row=>!['complete','skipped'].includes(row.status)&&routineFitsNow(row)).forEach(row=>addFlex('routine',row,55));if(school.nextStep)addFlex('study',{...school.nextStep,id:school.nextStep.id||'focus',minutes:30},45);
 return{snapshot,state,date,daily,health,work,school,finance,life,fixed,flexible,day:view==='home'?buildAdaptiveDay({nowMinutes:localClock(),fixed,flexible}):{active:null,next:null,pocketMinutes:0,recommendation:null}};
}

