function palaceNavAttributes(id,route,lane=''){if(route===null)return`data-v6-nav="${esc(id)}" data-v6-future="${esc(id)}"`;const view=route||id;return`data-v6-nav="${esc(id)}" data-route-view="${esc(view)}"${lane?` data-route-lane="${esc(lane)}"`:''}`}
function palaceDock(){
 const primary=[['home','🏰','Foyer'],['daily','🎀','Duties'],['time','📅','Calendar'],['boss','👑','Career'],['carriage-house','🎠','Carriage','money'],['hobbies','🌹','Garden']],remaining=[['BUILD MY KINGDOM',[['royal-kitchen','🍽️','Royal Kitchen',null],['study','📚','Scholar’s Tower'],['money','💰','Royal Treasury']]],['MY WORLD',[['moon-garden','🌙','Moon Garden',null],['love-letters','💌','Love Letters',null],['wishing-tower','✨','Wishing Tower',null]]],['KEEP & REMEMBER',[['archive','🎁','Keepsake Chest'],['royal-archives','📖','Royal Archives',null]]],['TOOLS',[['bell-tower','🔔','Bell Tower',null],['mochini','🍡','Mochini'],['settings','⚙️','Settings']]]],selected=activeFuture||activeNav||defaultNav(currentView());
 const dock=app.querySelector('[data-palace-dock]')||document.createElement('nav');dock.dataset.palaceDock='';dock.className='palace-dock';dock.setAttribute('aria-label','Palace navigation');dock.innerHTML=`${primary.map(([id,icon,label,route,lane])=>`<button type="button" class="${selected===id?'active':''}" ${palaceNavAttributes(id,route,lane)}><span>${icon}</span><small>${label}</small></button>`).join('')}<button type="button" class="${roomsOpen?'active':''}" data-palace-rooms aria-expanded="${roomsOpen}"><span>🏛</span><small>Rooms</small></button>`;if(!dock.isConnected)app.append(dock);
 const drawer=app.querySelector('[data-palace-drawer]')||document.createElement('div');drawer.dataset.palaceDrawer='';drawer.className='palace-rooms-backdrop';drawer.hidden=!roomsOpen;drawer.innerHTML=`<section class="palace-rooms-drawer" role="dialog" aria-modal="true" aria-label="Palace Rooms"><header><div><div class="ey">🏛 PALACE ROOMS</div><h2>Where would you like to go?</h2></div><button type="button" class="detail-modal-close" data-palace-rooms-close aria-label="Close Rooms">×</button></header><div class="palace-room-groups">${remaining.map(([group,items])=>`<section><small>${group}</small><div>${items.map(([id,icon,label,route,lane])=>`<button type="button" class="${selected===id?'active':''}" ${palaceNavAttributes(id,route,lane)}><span>${icon}</span><b>${label}</b></button>`).join('')}</div></section>`).join('')}</div></section>`;if(!drawer.isConnected)app.append(drawer);
}
function brandShell(){
 document.title='KatOS V6 · The Palace';document.documentElement.dataset.katosVersion='6';
 const brand=app.querySelector('.brand h1'),build=app.querySelector('.brand .build'),foot=app.querySelector('.sidebar-foot'),scribble=app.querySelector('.brand .scribble');if(brand)brand.textContent='The Palace';if(build)build.textContent='6.9.4 · Career Stability';if(foot)foot.innerHTML='<b>KatOS V6</b><br>The Living Palace, room by room.';if(scribble)scribble.textContent='a softer way to hold a life';
 const view=currentView();if(!activeNav)activeNav=defaultNav(view);
 document.documentElement.dataset.v6ActiveRoom=activeFuture||activeNav||defaultNav(view)||view;
 const nav=app.querySelector('.nav');if(nav){const buttons=new Map([...nav.querySelectorAll('.nav-btn[data-view]')].map(button=>[button.dataset.view,button]));nav.replaceChildren();NAV_GROUPS.forEach(([group,items])=>{if(group){const heading=document.createElement('div');heading.className='v6-nav-group-label';heading.textContent=group;nav.append(heading)}items.forEach(([id,icon,label,route,lane])=>{let button=route===undefined?buttons.get(id):null;if(!button){button=document.createElement('button');button.type='button';button.className='nav-btn';button.innerHTML='<span class="nav-icon"></span><span></span>';if(route)button.dataset.routeView=route;else button.dataset.v6Future=id}button.hidden=false;button.dataset.v6Nav=id;if(lane)button.dataset.routeLane=lane;button.querySelector('.nav-icon').textContent=icon;button.querySelector(':scope > span:last-child').textContent=label;button.classList.toggle('active',id===(activeFuture||activeNav||defaultNav(view)));nav.append(button)})})}
 const title=app.querySelector('.top-title');if(title)title.textContent=activeFuture?(NEW_ROOM_LABELS[activeFuture]||FUTURE_ROOMS[activeFuture]?.[1]||'The Palace'):NAV.find(([id,,,route])=>id===(activeNav||defaultNav(view))&&route!==null)?.[2]||ROOM_LABELS[view]||'The Palace';
 app.querySelectorAll('.ey,.room-source').forEach(node=>{if(node.childElementCount===0)node.textContent=node.textContent.replace(/\bV5\b/g,'V6')});
 palaceDock();
}

function sourceSections(page){return[...page.children].filter(node=>!node.matches('.v6-command-room,.v6-detail-toolbar')).filter(node=>!node.classList.contains('detail-modal-backdrop'))}
function integrateSource(view,page){
 const room=page.querySelector('.v6-command-room');if(!room)return;
 const sources=sourceSections(page),cards=[];sources.forEach(source=>source.querySelectorAll('.card').forEach(candidate=>{if(!candidate.parentElement?.closest('.card')&&!cards.includes(candidate))cards.push(candidate)}));
 const targetFor=card=>{
  const heading=text(card.querySelector('h2')?.textContent).toLowerCase(),marker=`${text(card.querySelector('.ey')?.textContent)} ${heading} ${text(card.className)}`.toLowerCase();
  if(view==='money'){if(/account|money right now|balance/.test(marker))return'accounts';if(/goal|saving|fund|money with a purpose/.test(marker))return'goals';if(/real money ledger|ledger|transaction|actual paper trail|recent activity/.test(marker))return'ledger';if(/bill|subscription|budget|cash flow|liabilit|work estimate|spending|gig snapshot/.test(marker))return'tools'}
  if(view==='study'){if(/assignment|learning queue|deadline|study session/.test(heading))return'assignments';if(/course|program|degree/.test(heading))return'courses'}
  return'tools';
 };
 cards.forEach(card=>{const target=targetFor(card),slot=room.querySelector(`[data-v6-slot="${target}"]`)||room.querySelector('[data-v6-slot="tools"]');if(!slot)return;card.classList.add('v6-native-card');if(view==='money'&&['accounts','goals','ledger'].includes(target))card.classList.remove('tiny-hide');slot.append(card)});
 const tools=room.querySelector('[data-v6-slot="tools"]');if(tools)sources.filter(node=>!node.matches('.hero,.stat-grid,.room-stat-grid,.grid')&&!node.querySelector('.card')&&text(node.textContent)).forEach(node=>{node.classList.remove('v6-source-section');node.classList.add('v6-native-panel');tools.append(node)});
 room.querySelectorAll('[data-v6-slot]').forEach(slot=>{if(!slot.children.length)slot.innerHTML='<p class="v6-soft-empty">Nothing is waiting in this section.</p>'});
}
function showOverview(view){
 const page=app.querySelector('.main>.page');if(!page)return;if(view==='hobbies'){renderNewRoom('rose-garden',page);return}const identity=view==='money'&&activeNav==='carriage-house'?'carriage':view,existing=page.querySelector('.v6-command-room');
 if(existing){
  if(identity==='carriage')existing.remove();
  else if(existing.dataset.v6Room===identity&&!forceNativeRefresh){if(LEGACY_PRESENTATION_VIEWS.has(identity))integrateSource(identity,page);return}
  else existing.remove();
 }
 let markup;try{markup=roomMarkup(view,data(view))}catch(error){console.error(`KatOS V6 could not render ${identity}.`,error);recoverInteractivity();markup=`${hero('🌸 PALACE RECOVERY','This room hit a display snag.','Your data was not changed. The Palace stayed interactive so you can retry or return to the Foyer.')}<section class="v6-command-card"><div class="ey">SAFE RECOVERY</div><h2>${esc(identity==='boss'?'Crown & Career is still here.':'The room is still here.')}</h2><p>Close any leftover popup and rebuild this room from its canonical records.</p><div class="button-row"><button type="button" class="btn primary" data-v6-retry-room>Retry room</button><button type="button" class="btn soft" data-v6-nav="home" data-route-view="home">Return to Foyer</button></div></section>`}if(!markup)return;
 page.classList.remove('v6-detail-mode');page.classList.add('v6-overview-mode');sourceSections(page).forEach(node=>node.classList.add('v6-source-section'));
 page.querySelector('.v6-detail-toolbar')?.remove();page.insertAdjacentHTML('beforeend',`<div class="v6-command-room" data-v6-room="${esc(identity)}">${markup}</div>`);forceNativeRefresh=false;if(LEGACY_PRESENTATION_VIEWS.has(identity))integrateSource(identity,page);
}
function decorate(){recoverInteractivity();const selected=app.querySelector('.nav-btn.active[data-view]')?.dataset.view;if(selected)activeView=selected;brandShell();const view=currentView();if(activeFuture){showFutureRoom(activeFuture);return}if(LABELS[view]&&!['mochini','settings'].includes(view))showOverview(view);decorateSmartPalace();decorateLivingPalace()}
let queued=false;function queue(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;decorate()})}
window.addEventListener('katos:v6-native-refresh',()=>{forceNativeRefresh=true;queue()});

app.addEventListener('submit',event=>{const winForm=event.target.closest('[data-foyer-win-form]');if(winForm){event.preventDefault();event.stopImmediatePropagation();const values=new FormData(winForm),result=runV5LifestyleAction({type:'growth-win-save',title:text(values.get('title')),date:localDateKey(),areaId:'',notes:''});if(!result.ok){winForm.querySelector('[data-foyer-win-error]').textContent=result.error||'That win could not be saved.';return}winForm.closest('[data-foyer-win-modal]')?.remove();window.dispatchEvent(new Event('katos:v6-refresh'));return}if(event.target.closest('[data-flex-shift-form],[data-doordash-shift-form],[data-money-form],[data-smart-form="adaptive"]'))requestAnimationFrame(()=>requestAnimationFrame(queue))},true);
app.addEventListener('click',event=>{
 const foyerAnchor=event.target.closest('[data-foyer-anchor="right-now"]');if(foyerAnchor){event.preventDefault();app.querySelector('[data-foyer-right-now]')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});return}
 const tinyWin=event.target.closest('[data-foyer-tiny-win]');if(tinyWin){event.preventDefault();event.stopImmediatePropagation();app.querySelector('[data-foyer-win-modal]')?.remove();const modal=document.createElement('div');modal.className='detail-modal-backdrop v6-foyer-win-modal';modal.dataset.foyerWinModal='';modal.innerHTML=`<section class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="foyer-win-title"><header class="v6-popup-header"><div><div class="ey">✨ TINY WIN</div><h2 id="foyer-win-title">What counted?</h2><p>No score. No streak. Just one thing worth noticing.</p></div><button type="button" class="detail-modal-close" data-foyer-win-close aria-label="Close">×</button></header><form data-foyer-win-form><label class="wide">Tiny win<input name="title" required maxlength="160" autocomplete="off" placeholder="I did the small thing."></label><p class="v6-form-error" data-foyer-win-error></p><div class="button-row"><button type="button" class="btn soft" data-foyer-win-close>Cancel</button><button type="submit" class="btn primary">Save Win</button></div></form></section>`;app.append(modal);modal.querySelector('input')?.focus();return}
 const winClose=event.target.closest('[data-foyer-win-close]');if(winClose||event.target.matches('[data-foyer-win-modal]')){event.preventDefault();event.target.closest('[data-foyer-win-modal]')?.remove();return}
 const kitchenPreview=event.target.closest('[data-foyer-preview="kitchen"]');if(kitchenPreview){event.preventDefault();event.stopImmediatePropagation();app.querySelector('[data-foyer-preview-modal]')?.remove();const preview=document.createElement('div');preview.className='detail-modal-backdrop v6-foyer-preview-modal';preview.dataset.foyerPreviewModal='';preview.innerHTML='<section class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="foyer-kitchen-title"><header class="v6-popup-header"><div><div class="ey">🍽️ ROYAL KITCHEN</div><h2 id="foyer-kitchen-title">The meal-prep studio is being set.</h2><p>This Foyer card is a visual preview. No meal data was created or changed in this pass.</p></div><button type="button" class="detail-modal-close" data-foyer-preview-close aria-label="Close">×</button></header><div class="v6-foyer-preview-body"><span aria-hidden="true">🍓</span><p>Weekly meal prep, recipes, groceries, and prep-day tools will keep their own room composition.</p></div><div class="button-row"><button type="button" class="btn primary" data-foyer-preview-close>Close</button></div></section>';app.append(preview);preview.querySelector('[data-foyer-preview-close]')?.focus();return}
 const previewClose=event.target.closest('[data-foyer-preview-close]');if(previewClose||event.target.matches('[data-foyer-preview-modal]')){event.preventDefault();event.target.closest('[data-foyer-preview-modal]')?.remove();return}
 const roomsButton=event.target.closest('[data-palace-rooms]');if(roomsButton){event.preventDefault();event.stopImmediatePropagation();roomsOpen=!roomsOpen;palaceDock();return}
 const roomsClose=event.target.closest('[data-palace-rooms-close]');if(roomsClose||event.target.matches('[data-palace-drawer]')){event.preventDefault();roomsOpen=false;palaceDock();return}
 const retryRoom=event.target.closest('[data-v6-retry-room]');if(retryRoom){event.preventDefault();closeTransientSurfaces();forceNativeRefresh=true;queue();return}
 const palaceNav=event.target.closest('[data-v6-nav]');if(palaceNav){closeTransientSurfaces();activeNav=palaceNav.dataset.v6Nav;activeFuture=null;activeView=palaceNav.dataset.routeView||palaceNav.dataset.view||activeView;if(palaceNav.dataset.v6Future){event.preventDefault();event.stopImmediatePropagation();showFutureRoom(palaceNav.dataset.v6Future);return}requestAnimationFrame(()=>requestAnimationFrame(queue))}
 if(palaceNav){roomsOpen=false;app.querySelector('[data-palace-drawer]')?.setAttribute('hidden','')}
 const route=event.target.closest('[data-route-view]');if(route&&!palaceNav){closeTransientSurfaces();activeView=route.dataset.routeView||activeView;activeNav=route.dataset.routeLane==='gig'?'carriage-house':defaultNav(activeView);activeFuture=null;requestAnimationFrame(()=>requestAnimationFrame(queue))}
 const dutyPanel=event.target.closest('[data-v6-duty-details]');if(dutyPanel){event.preventDefault();const details=app.querySelector(`[data-v6-duty-panel="${CSS.escape(dutyPanel.dataset.v6DutyDetails)}"]`);if(details){details.open=true;details.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}return}
 const jump=event.target.closest('[data-v6-jump]');if(jump){event.preventDefault();app.querySelector(`[data-v6-slot="${jump.dataset.v6Jump}"]`)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
 const archiveGoal=event.target.closest('[data-v6-gig-goal-archive]');if(archiveGoal){event.preventDefault();event.stopImmediatePropagation();if(!window.confirm('Archive this completed gig goal? It will move to Keepsake Chest and can be restored later.'))return;const result=archiveV5Record('work.gig.goals',archiveGoal.dataset.v6GigGoalArchive);if(!result.ok){window.alert(result.error||'That gig goal could not be archived.');return}archiveGoal.closest('[data-money-modal]')?.remove();queue();return}
 const treasuryOpen=event.target.closest('[data-v6-room="money"] [data-money-open]');if(treasuryOpen){const modal=[...app.querySelectorAll('[data-money-modal]')].find(node=>node.dataset.moneyModal===treasuryOpen.dataset.moneyOpen);if(modal){event.preventDefault();event.stopImmediatePropagation();app.append(modal);modal.hidden=false;modal.querySelector('input,select,textarea')?.focus();return}}
 const preserveNative=event.target.closest('summary,button,input,select,textarea,a,[data-money-open],[data-money-close],[data-flex-plan-open],[data-doordash-plan-open],[data-gig-checkin-modal],[data-flex-shift-modal],[data-doordash-shift-modal]');
 if(preserveNative)return;
},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&roomsOpen){roomsOpen=false;palaceDock()}});
document.addEventListener('pointerdown',recoverOnContact,true);
document.addEventListener('touchstart',recoverOnContact,{capture:true,passive:false});
window.addEventListener('katos:rendered',queue);
window.addEventListener('pageshow',()=>{recoverInteractivity();queue()});
window.addEventListener('katos:v6-refresh',queue);
window.addEventListener('katos:v6-navigate',event=>{const id=event.detail?.id;if(!id)return;const target=app.querySelector(`[data-v6-nav="${CSS.escape(id)}"]`)||app.querySelector(`[data-route-view="${CSS.escape(id)}"]`);target?.click()});
window.addEventListener('storage',queue);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)queue()});
decorate();
